const BUILTIN_JOBS=[{"file": "jemwenti.txt", "code": "(function () {\n  const SKILLS = ['jw_shadow', 'jw_blast', 'jw_barrier', 'jw_ult'];\n  const VEX_N = 3;        // 벡스 수\n  const MAX_MARK = 5;     // 적 한 명당 표식 최대\n  const MARK_TICKS = 300; // 표식 지속 15초\n\n  function say(api, p, text) { api.actionbar(p, text); }\n\n  // 벡스가 소환되어 있는지\n  function vexOn(p, api) {\n    const v = p.st.vex;\n    return !!v && api.tick() < v.until && v.hp > 0;\n  }\n\n  // 벡스 위치: 내 머리 위를 날아다님 (블록과 상관없이 떠다니는 입자)\n  function vexPos(p, i, now) {\n    const a = now * 0.12 + i * (Math.PI * 2 / VEX_N);\n    return {\n      x: p.x + Math.cos(a) * 1.6,\n      y: p.y + 2.6 + Math.sin(now * 0.2 + i * 2) * 0.3,\n      z: p.z + Math.sin(a) * 1.6,\n    };\n  }\n\n  // 벡스 추가타: 벽을 통과해 날아가서 0.5초 뒤 방어 무시 3 피해 + 내 체력 1 회복\n  // (무적 시간 때문에 바로 주면 무시되므로 10틱 늦춤)\n  function vexStrike(p, t, api) {\n    if (!vexOn(p, api)) return;\n    const v = p.st.vex;\n    v.next = ((v.next || 0) + 1) % VEX_N;\n    const from = vexPos(p, v.next, api.tick());\n    api.line(from, { x: t.x, y: t.y + 1.2, z: t.z }, [0.6, 0.8, 1], 0.5);\n    api.after(10, () => {\n      if (!p.alive || !t || t.hp <= 0) return;\n      api.damage(t, 3, { by: p, type: 'magic' });\n      api.heal(p, 1);\n      api.particles('dust', t.x, t.y + 1, t.z, 4, [0.6, 0.8, 1]);\n    });\n  }\n\n  // 마법 그림자에 맞은 적에게 표식 +1\n  function addMark(p, t, api) {\n    if (!t || t.kind === 'mob' || t.id === undefined) return;\n    const st = p.st;\n    st.marks = st.marks || {};\n    const m = st.marks[t.id] || { t: t, n: 0, until: 0 };\n    m.t = t;\n    m.n = Math.min(MAX_MARK, m.n + 1);\n    m.until = api.tick() + MARK_TICKS;\n    st.marks[t.id] = m;\n    api.particles('dust', t.x, t.y + 2.3, t.z, 4 + m.n * 2, [0.5, 0.1, 0.8]);\n    say(api, p, '§5표식 §f' + m.n + '/' + MAX_MARK + ' §7(' + (t.name || '적') + ')');\n  }\n\n  // 벡스가 모두 쓰러짐\n  function vexDown(p, api) {\n    api.heal(p, 5);\n    p.st.vex = null;\n    api.particles('dust', p.x, p.y + 2.6, p.z, 12, [0.6, 0.8, 1]);\n    say(api, p, '§b벡스가 쓰러졌다 §a체력 +5');\n  }\n\n  APVP.addJob({\n    id: 'jemwenti',\n    name: '젬웬티', icon: '👻',\n    desc: '원거리 마법형 · 그림자 표식 + 벡스 소환',\n    maxHp: 20,\n    speed: 1,\n    kit: ['jw_staff', 'jw_shadow', 'jw_blast', 'jw_barrier', 'jw_ult'],\n    items: {\n      jw_staff: {\n        type: 'weapon', name: '강령술사의 지팡이', icon: '🪄', mc: 'bone',\n        damage: 5, speed: 1.6,\n        lore: '벡스가 있는 동안 맞힌 적에게 추가타',\n      },\n      jw_shadow: {\n        type: 'skill', name: '마법 그림자', icon: '🌑', mc: 'echo_shard', cooldown: 5,\n        lore: '직선 그림자 마법 2 피해 · 맞은 적에게 표식 +1 · 맞히면 쿨타임 2초 감소 · 사용 시 내 디버프 제거',\n        use(p, api) {\n          // 내게 걸린 디버프 제거\n          for (const n of ['slowness', 'weakness', 'poison', 'glowing']) api.clearEffect(p, n);\n          api.synth({ wave: 'sawtooth', freq: 420, to: 140, dur: 0.25, vol: 0.4 }, p);\n          api.projectile(p, {\n            speed: 1.3, gravity: 0, size: 0.35, life: 3,\n            damage: 2, type: 'magic', knockback: 0.3, pierce: false,\n            color: [0.45, 0.1, 0.7], trail: 3,\n            onHit(t, pos, api) {\n              api.particles('dust', pos.x, pos.y, pos.z, 8, [0.45, 0.1, 0.7]);\n              // 맞히면 남은 쿨타임 2초 감소\n              api.setCooldown(p, 'jw_shadow', Math.max(0, api.cooldown(p, 'jw_shadow') - 2));\n              addMark(p, t, api);\n              vexStrike(p, t, api);\n            },\n          });\n          return true;\n        },\n      },\n      jw_blast: {\n        type: 'skill', name: '그림자 폭발', icon: '💥', mc: 'nether_star', cooldown: 12,\n        lore: '표식이 있는 모든 적에게 3초 뒤 폭발 6 피해 · 표식 5개가 쌓인 적은 처형 · 표식 수만큼 힘 레벨 5초 · 표식 소모',\n        use(p, api) {\n          const now = api.tick();\n          const marks = p.st.marks || {};\n          const list = Object.values(marks).filter((m) => m.t && m.t.hp > 0 && now <= m.until && m.n > 0);\n          if (!list.length) { say(api, p, '§7표식이 있는 적이 없습니다'); return false; }\n\n          // 표식이 있는 만큼 공격력(힘)이 올라감\n          let total = 0;\n          for (const m of list) total += m.n;\n          const lv = Math.min(MAX_MARK, total);\n          api.effect(p, 'strength', lv, 5);\n          p.st.marks = {}; // 표식 소모\n\n          api.synth({ wave: 'sine', freq: 200, to: 90, dur: 0.4, vol: 0.5 }, p);\n          api.title(p, '§5그림자 폭발', '§f힘 ' + lv + ' · 표식 ' + total + '개');\n\n          for (const m of list) {\n            const t = m.t;\n            let lx = t.x, lz = t.z;\n            if (t.kind !== 'mob') api.effect(t, 'glowing', 1, 3);\n            api.ring(t.x, t.y + 0.1, t.z, 3, [0.5, 0.1, 0.8], 24);\n            for (let i = 10; i < 60; i += 10) {\n              api.after(i, () => {\n                if (t.hp <= 0) return;\n                lx = t.x; lz = t.z;\n                api.ring(t.x, t.y + 0.1, t.z, 3, [0.5, 0.1, 0.8], 24);\n                api.particles('dust', t.x, t.y + 2.2, t.z, 3, [0.5, 0.1, 0.8]);\n              });\n            }\n            api.after(60, () => {\n              if (!p.alive || t.hp <= 0) return;\n              if (Math.hypot(t.x - lx, t.z - lz) > 8) return; // 죽어서 멀리 부활했으면 취소\n              // 표식 5개(최대)가 쌓인 적은 처형\n              if (m.n >= MAX_MARK) {\n                api.particles('dust', t.x, t.y + 1.2, t.z, 30, [0.35, 0, 0.5]); api.ring(t.x, t.y + 0.1, t.z, 1.5, [0.8, 0.1, 0.9], 30);\n                say(api, p, '§5§l처형! §f' + (t.name || '적'));\n                api.damage(t, 1000, { by: p, type: 'magic' });\n              }\n              const hit = api.explode(p, t.x, t.y + 0.5, t.z, 3, 6, { knockback: 0.8, falloff: false, self: false, sound: true });\n              api.particles('dust', t.x, t.y + 1, t.z, 12, [0.5, 0.1, 0.8]);\n              for (const e of (hit || [])) vexStrike(p, e, api);\n            });\n          }\n          return true;\n        },\n      },\n      jw_barrier: {\n        type: 'skill', name: '그림자 방벽', icon: '🛡️', mc: 'phantom_membrane', cooldown: 20,\n        lore: '6초 동안 다음 1회 피해 무효 · 막은 피해의 50%를 공격자에게 반사',\n        use(p, api) {\n          p.st.barrier = { until: api.tick() + 120 };\n          api.sound('shield_', p, 20, 0.8);\n          api.ring(p.x, p.y + 0.1, p.z, 1.5, [0.4, 0.1, 0.6], 20);\n          api.particles('dust', p.x, p.y + 1, p.z, 10, [0.4, 0.1, 0.6]);\n          say(api, p, '§5그림자 방벽 §f발동 §7(6초)');\n          return true;\n        },\n      },\n      jw_ult: {\n        type: 'skill', name: '유령님 한턴해요', icon: '👻', mc: 'ghast_tear', cooldown: 45,\n        lore: '하늘을 날고 벽을 통과하는 벡스 3마리 소환 15초 · 받는 피해 50% 대신 맞음 · 내 공격마다 추가타 3',\n        use(p, api) {\n          const now = api.tick();\n          p.st.vex = { since: now, until: now + 300, hp: 40, next: 0 };\n          api.synth({ wave: 'sine', freq: 300, to: 120, dur: 0.6, vol: 0.5 }, p);\n          api.ring(p.x, p.y + 0.1, p.z, 2, [0.6, 0.8, 1], 24);\n          for (let i = 0; i < VEX_N; i++) {\n            const pos = vexPos(p, i, now);\n            api.particles('dust', pos.x, pos.y, pos.z, 8, [0.6, 0.8, 1]);\n          }\n          api.title(p, '§b유령님 한턴해요!', '§7벡스 ' + VEX_N + '마리 소환');\n          return true;\n        },\n      },\n    },\n\n    tick(p, api) {\n      const st = p.st, now = api.tick();\n\n      // ── 벡스: 입자로 날아다님 / 초당 체력 회복 / 지속시간 ──\n      const v = st.vex;\n      if (v) {\n        if (now >= v.until) {\n          st.vex = null;\n          say(api, p, '§7벡스가 사라졌습니다');\n        } else {\n          if (now % 20 === 0) v.hp = Math.min(40, v.hp + 1);\n          if (now % 2 === 0) {\n            for (let i = 0; i < VEX_N; i++) {\n              const pos = vexPos(p, i, now);\n              api.particles('dust', pos.x, pos.y, pos.z, 2, [0.6, 0.8, 1]);\n              if (now % 6 === 0) api.particles('glow', pos.x, pos.y, pos.z, 1);\n            }\n          }\n        }\n      }\n\n      // ── 표식: 지속시간 확인 / 머리 위 표시 ──\n      if (st.marks) {\n        for (const id of Object.keys(st.marks)) {\n          const m = st.marks[id];\n          if (!m.t || m.t.hp <= 0 || now > m.until) { delete st.marks[id]; continue; }\n          if (now % 10 === 0) api.particles('dust', m.t.x, m.t.y + 2.3, m.t.z, m.n * 2, [0.5, 0.1, 0.8]);\n        }\n      }\n\n      // ── 그림자 방벽 ──\n      const b = st.barrier;\n      if (b) {\n        if (now > b.until) {\n          st.barrier = null;\n          api.actionbar(p, '§7그림자 방벽이 사라졌습니다');\n        } else if (now % 6 === 0) {\n          api.particles('dust', p.x, p.y + 1, p.z, 5, [0.4, 0.1, 0.6]);\n        }\n      }\n    },\n\n    hit(p, t, damage, api) {\n      vexStrike(p, t, api); // 벡스가 있으면 추가타\n    },\n\n    hurt(p, amount, src, api) {\n      if (!p.alive || p.hp <= 0) return;\n      if (!src || src.by == null || src.by === p.id) return; // 환경 · 자해 피해는 제외\n\n      // 그림자 방벽: 다음 1회 피해 무효 + 50% 반사\n      const b = p.st.barrier;\n      if (b && api.tick() <= b.until) {\n        api.heal(p, amount);\n        p.st.barrier = null;\n        const att = api.players().find((q) => q.id === src.by);\n        if (att) api.damage(att, amount * 0.5, { by: p, type: 'magic' });\n        api.sound('shieldbreak_', p, 20, 0.7);\n        api.particles('dust', p.x, p.y + 1, p.z, 12, [0.4, 0.1, 0.6]);\n        say(api, p, '§5그림자 방벽 §f반사!');\n        return;\n      }\n\n      // 벡스: 받는 피해의 50%를 대신 맞음 (공유 체력 40)\n      if (vexOn(p, api)) {\n        const half = amount * 0.5;\n        api.heal(p, half);\n        p.st.vex.hp -= half;\n        api.particles('dust', p.x, p.y + 2.6, p.z, 6, [0.6, 0.8, 1]);\n        if (p.st.vex.hp <= 0) vexDown(p, api);\n      }\n    },\n\n    // 특성: 처치하면 영혼 폭발 + 모든 스킬 쿨타임 2초 감소\n    kill(p, victim, pos, api) {\n      if (victim && p.st.marks) delete p.st.marks[victim.id];\n      const list = api.enemiesAt(p, pos.x, pos.y, pos.z, 5);\n      for (const t of list) {\n        api.damage(t, 3, { by: p, type: 'magic' });\n        api.particles('dust', t.x, t.y + 1, t.z, 6, [0.5, 0.2, 0.8]);\n      }\n      api.ring(pos.x, pos.y + 0.1, pos.z, 5, [0.5, 0.2, 0.8], 32);\n      api.particles('dust', pos.x, pos.y + 1, pos.z, 16, [0.5, 0.2, 0.8]);\n      api.synth({ wave: 'triangle', freq: 500, to: 150, dur: 0.4, vol: 0.4 }, p);\n      for (const id of SKILLS) {\n        const c = api.cooldown(p, id);\n        if (c > 0) api.setCooldown(p, id, Math.max(0, c - 2));\n      }\n      say(api, p, '§d영혼 폭발! §7쿨타임 -2초');\n    },\n\n    respawn(p, api) {\n      say(api, p, '§b젬웬티 §7- 이세계에서도 강령술은 통한다');\n    },\n\n    bot(p, t, dist, api) {\n      if (dist < 30) api.useItem(p, 'jw_shadow');\n      if (dist < 35) api.useItem(p, 'jw_blast');\n      if (dist < 12) api.useItem(p, 'jw_ult');\n      if (p.hp < 12) api.useItem(p, 'jw_barrier');\n    },\n  });\n})();", "snd": {}}, {"file": "yuntomman.txt", "code": "(function () {\n  const SND = '윤톰맨';\n  const BOOM_TICKS = 600;   // 자폭까지 30초\n  const INV_TICKS = 60;     // 자폭 3초 전부터 무적\n  const CHASE_TICKS = 200;  // 윤톰맨! 사용 시 자폭 시간 10초\n\n  // 폭탄 설치 중첩에 따른 피해 배율 (+30% × 중첩)\n  function mult(p) { return 1 + 0.3 * ((p.st && p.st.bombs) || 0); }\n\n  // 자해 피해 (체력 1 아래로는 내려가지 않게 제한)\n  function selfHurt(p, api, amount) {\n    const a = Math.min(amount, p.hp - 1);\n    if (a > 0) api.damage(p, a, { by: p, type: 'magic' });\n  }\n\n  function say(api, p, text) { api.actionbar(p, text); }\n\n  // 스스로 죽기 전에 무적(저항)을 풀고 죽는다\n  function dieSelf(p, api) {\n    p.st.dying = true;\n    p.st.inv = false;\n    p.st.chase = null;\n    api.clearEffect(p, 'resistance');\n    api.clearEffect(p, 'speed');\n    api.damage(p, 999, { by: p, type: 'magic' });\n  }\n\n  function boom(p, api) {\n    const st = p.st;\n    st.dying = true;\n    st.boomAt = api.tick() + 99999; // 중복 폭발 방지\n    api.sound(SND, p, 30, 1);\n    api.ring(p.x, p.y + 0.1, p.z, 12, [1, 0.4, 0.1], 48);\n    api.ring(p.x, p.y + 1.5, p.z, 12, [1, 0.2, 0.1], 48);\n    api.particles('explosion', p.x, p.y + 1, p.z, 8);\n    api.explode(p, p.x, p.y + 0.5, p.z, 12, 10 * mult(p), { knockback: 1.5, falloff: false, self: false, sound: true });\n    api.title(p, '§c자폭!', '§7윤톰맨은 오늘도 일했다');\n    dieSelf(p, api);\n  }\n\n  // 윤톰맨! 돌격이 적에게 닿았을 때\n  function chaseHit(p, t, api) {\n    const st = p.st;\n    st.dying = true;\n    st.inv = false;\n    st.chase = null;\n    api.clearEffect(p, 'speed');\n    api.clearEffect(p, 'resistance');\n    const m = mult(p);\n    const maxH = api.maxHp(t);\n    const frac = api.hp(t) / maxH;\n    if (frac < 0.5) {\n      // 즉시 처치\n      api.damage(t, api.hp(t) + 100, { by: p, type: 'magic' });\n    } else {\n      api.damage(t, maxH * 0.4 * m, { by: p, type: 'melee', knockback: 1 });\n    }\n    api.particles('explosion', t.x, t.y + 1, t.z, 6);\n    api.particles('flame', t.x, t.y + 1, t.z, 12);\n    api.sound(SND, p, 30, 1);\n    // 사용 후 나도 사망\n    api.after(6, () => {\n      if (p.alive) { api.clearEffect(p, 'resistance'); api.damage(p, 999, { by: p, type: 'magic' }); }\n    });\n  }\n\n  APVP.addJob({\n    id: 'yuntomman',\n    name: '윤톰맨', icon: '💣',\n    desc: '자폭형 · 폭발 + 폭탄 설치 + 30초 자폭',\n    maxHp: 15,\n    speed: 1.1,\n    kit: ['yt_blast', 'yt_surprise', 'yt_bomb', 'yt_ult'],\n    items: {\n      yt_blast: {\n        type: 'weapon', name: '폭발', icon: '💥', mc: ['block/tnt_side', 'block/tnt_top'],\n        damage: 1, speed: 0.6,\n        lore: '잃은 체력이 많을수록 강해짐 (3 + 잃은 체력×0.8, 최대 12) · 나에게 4 피해 · 공격 시 자폭 시간 +1초',\n      },\n      yt_surprise: {\n        type: 'skill', name: '서프라이즈', icon: '🎁', mc: 'firework_rocket', cooldown: 12,\n        lore: '40칸 안의 모든 적에게 방어 무시 3 마법 피해 + 위치 표시 · 적중 시 자폭 시간 +1초',\n        use(p, api) {\n          const list = api.enemies(p, 40);\n          if (!list.length) { say(api, p, '§7주변에 적이 없습니다'); return false; }\n          api.sound(SND, p, 30, 1);\n          const dmg = 3 * mult(p);\n          let hitPlayer = false;\n          for (const t of list) {\n            api.damage(t, dmg, { by: p, type: 'magic' });\n            if (t.kind !== 'mob') { api.effect(t, 'glowing', 1, 2); hitPlayer = true; }\n            api.particles('explosion', t.x, t.y + 1, t.z, 2);\n            api.particles('crit', t.x, t.y + 1.5, t.z, 6);\n          }\n          if (hitPlayer && p.st.boomAt !== undefined) p.st.boomAt += 20; // 공격 시 자폭 +1초\n          api.title(p, '§e서프라이즈!', '');\n          return true;\n        },\n      },\n      yt_bomb: {\n        type: 'skill', name: '폭탄 설치', icon: '🧨', mc: 'gunpowder', cooldown: 20,\n        lore: '나에게 3 피해 · 내 모든 능력 피해 영구 +30% (최대 3중첩 · 사망 시 사라짐)',\n        use(p, api) {\n          const n = p.st.bombs || 0;\n          if (n >= 3) { say(api, p, '§7폭탄 설치는 최대 3중첩입니다'); return false; }\n          if (p.hp <= 3) { say(api, p, '§c체력이 부족해서 설치할 수 없습니다'); return false; }\n          api.sound(SND, p, 30, 1);\n          api.damage(p, 3, { by: p, type: 'magic' });\n          p.st.bombs = n + 1;\n          api.particles('flame', p.x, p.y + 1, p.z, 10);\n          api.particles('poof', p.x, p.y + 0.5, p.z, 6);\n          say(api, p, '§c폭탄 설치! §f피해량 +' + (p.st.bombs * 30) + '% §7(' + p.st.bombs + '/3)');\n          return true;\n        },\n      },\n      yt_ult: {\n        type: 'skill', name: '윤톰맨!', icon: '🦞', mc: 'fire_charge', cooldown: 45,\n        lore: '자폭 시간 10초로 단축 · 적에게 돌격 (가까워질수록 이속 증가) · 닿으면 최대체력 40% 피해 · 체력 50% 미만이면 즉시 처치 · 이후 나도 사망',\n        use(p, api) {\n          const t = api.raycast(p, 30) || api.nearestEnemy(p, 30);\n          if (!t) { say(api, p, '§7대상이 없습니다'); return false; }\n          const now = api.tick();\n          api.sound(SND, p, 30, 1);\n          // 자폭 시간을 10초로 줄인다 (이미 10초보다 짧으면 그대로)\n          p.st.boomAt = Math.min(p.st.boomAt === undefined ? now + CHASE_TICKS : p.st.boomAt, now + CHASE_TICKS);\n          p.st.chase = { t: t, until: now + CHASE_TICKS };\n          api.line({ x: p.x, y: p.y + 1, z: p.z }, { x: t.x, y: t.y + 1, z: t.z }, [1, 0.4, 0.1], 0.4);\n          api.dash(p, 1.0, 0.2);\n          api.title(p, '§c윤톰맨!', '§710초 안에 닿아라');\n          return true;\n        },\n      },\n    },\n\n    // 특성: 자폭 타이머 + 3초 전 무적 + 윤톰맨! 돌격\n    tick(p, api) {\n      const st = p.st, now = api.tick();\n      if (st.dying) return;\n      if (st.boomAt === undefined) st.boomAt = now + BOOM_TICKS;\n\n      // ── 윤톰맨! 돌격: 가까워질수록 이동 속도 증가 ──\n      const c = st.chase;\n      if (c) {\n        const t = c.t;\n        const d = t ? api.dist(p, t) : 999;\n        if (!t || t.hp <= 0 || t.alive === false || now > c.until || d > 45) {\n          st.chase = null;\n          api.clearEffect(p, 'speed');\n        } else {\n          const lv = d > 20 ? 1 : d > 14 ? 2 : d > 9 ? 3 : d > 5 ? 4 : 5;\n          if (now % 4 === 0) api.effect(p, 'speed', lv, 1);\n          if (now % 2 === 0) api.particles('flame', p.x, p.y + 0.4, p.z, 2);\n          if (d <= 2.5) { chaseHit(p, t, api); return; }\n        }\n      }\n\n      const left = st.boomAt - now;\n      if (left <= 0) { boom(p, api); return; }\n\n      // ── 자폭 3초 전부터 무적: 체력이 1 아래로 내려가지 않음 ──\n      if (left <= INV_TICKS) {\n        if (!st.inv) {\n          st.inv = true;\n          api.effect(p, 'resistance', 5, 1);\n          api.title(p, '§6무적!', '§c곧 폭발합니다');\n        } else if (now % 4 === 0) {\n          api.effect(p, 'resistance', 5, 1);\n        }\n        if (now % 4 === 0) api.particles('totem', p.x, p.y + 1, p.z, 4);\n      } else if (st.inv) {\n        // 공격으로 시간이 늘어나 3초 밖으로 나가면 무적 해제\n        st.inv = false;\n        api.clearEffect(p, 'resistance');\n      }\n\n      if (now % 10 === 0) {\n        const sec = Math.ceil(left / 20);\n        const col = sec <= 5 ? '§c' : '§e';\n        say(api, p, col + '자폭까지 §f' + sec + '초' + (st.inv ? ' §6[무적]' : '') + (st.bombs ? ' §7| §c폭탄 ' + st.bombs + '/3' : ''));\n      }\n      if (left <= 100 && left % 20 === 0) {\n        api.synth({ wave: 'square', freq: 880, dur: 0.08, vol: 0.4 }, p);\n        api.ring(p.x, p.y + 0.1, p.z, 2, [1, 0.2, 0.1], 16);\n      }\n    },\n\n    // 기본 무기: 잃은 체력이 많을수록 강해짐 (3 + 잃은 체력 × 0.8, 최대 12) + 자해 4 + 자폭 시간 +1초\n    hit(p, t, damage, api) {\n      const now = api.tick();\n      if (p.st.lastBlast !== undefined && now - p.st.lastBlast < 30) return; // 공속 0.6 근사\n      p.st.lastBlast = now;\n      const lost = Math.max(0, p.maxHp() - p.hp);\n      const dmg = Math.min(12, 3 + lost * 0.8) * mult(p);\n      api.sound(SND, p, 30, 1);\n      api.damage(t, dmg, { by: p, type: 'melee', knockback: 0.5 });\n      api.particles('explosion', t.x, t.y + 1, t.z, 3);\n      if (lost >= 6) api.particles('flame', p.x, p.y + 1, p.z, 6); // 체력이 많이 깎이면 불꽃 표시\n      if (t.kind !== 'mob' && p.st.boomAt !== undefined) p.st.boomAt += 20; // 공격 시 자폭 +1초\n      selfHurt(p, api, 4);\n    },\n\n    // 패시브: 마학 2008 — 남은 체력 비율 × 50% 확률로 회피 / 무적 중에는 피해를 되돌림\n    hurt(p, amount, src, api) {\n      if (!p.alive || p.hp <= 0) return;\n      if (src && src.by === p.id) return; // 자해 피해는 제외\n      if (p.st.inv && !p.st.dying) { api.heal(p, amount); return; } // 무적 중: 받은 피해 되돌림\n      if (!src || src.by == null) return; // 환경 피해는 회피 제외\n      const before = p.hp + amount;\n      const chance = Math.max(0, Math.min(1, before / p.maxHp())) * 50;\n      if (api.chance(chance)) {\n        api.heal(p, amount);\n        api.particles('poof', p.x, p.y + 1, p.z, 8);\n        api.particles('totem', p.x, p.y + 1.5, p.z, 6);\n        say(api, p, '§b마학 2008 §f회피!');\n        api.synth({ wave: 'sine', freq: 600, to: 1200, dur: 0.12, vol: 0.3 }, p);\n      }\n    },\n\n    // 선택안: 적을 처치하면 자폭 타이머 +10초\n    kill(p, victim, pos, api) {\n      if (p.st.dying) return;\n      p.st.boomAt = (p.st.boomAt || api.tick()) + 200;\n      say(api, p, '§a처치! §f자폭 타이머 +10초');\n    },\n\n    respawn(p, api) {\n      p.st.boomAt = api.tick() + BOOM_TICKS;\n      p.st.bombs = 0;\n      say(api, p, '§c윤톰맨 §7- 30초 뒤 자폭합니다');\n    },\n\n    bot(p, t, dist, api) {\n      if (dist < 40) api.useItem(p, 'yt_surprise');\n      if ((p.st.bombs || 0) < 3 && p.hp > 9) api.useItem(p, 'yt_bomb');\n      if (dist < 15 && api.hp(t) / api.maxHp(t) < 0.5) api.useItem(p, 'yt_ult');\n    },\n  });\n})();", "snd": {"윤톰맨": "data:audio/mpeg;base64,"}}];
